   ========================================================= */
:root{
  --ink:#070a13;
  --ink-2:#0d1322;
  --ink-3:#141d31;
  --panel:rgba(10,15,28,.78);
  --panel-strong:rgba(9,13,24,.94);
  --line:rgba(236,213,160,.18);
  --line-strong:rgba(236,213,160,.42);
  --gold:#ecd59f;
  --gold-2:#c9a65a;
  --gold-3:#8f6f33;
  --ivory:#f6efdf;
  --muted:#a9a495;
  --blue:#7ec8e3;
  --violet:#b69cff;
  --red:#e86161;
  --green:#79d39a;
  --hp:#d85f62;
  --mana:#68aee8;
  --stam:#d8c065;
  --shadow:0 24px 80px rgba(0,0,0,.5);
  --serif:"Palatino Linotype","Book Antiqua",Palatino,Georgia,"Times New Roman",serif;
  --sans:Lato,"DejaVu Sans",Verdana,sans-serif;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;background:#05070d;color:var(--ivory);font-family:var(--sans);overflow:hidden;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
body{overscroll-behavior:none}
button,input{font:inherit;color:inherit}
button{cursor:pointer;border:0;background:none}
button:focus-visible,input:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
kbd{display:inline-flex;align-items:center;justify-content:center;min-width:20px;height:20px;padding:0 5px;border:1px solid rgba(255,255,255,.2);border-radius:4px;background:rgba(255,255,255,.07);font:600 10px/1 var(--sans);letter-spacing:.02em;color:#e7e1d2;box-shadow:inset 0 -1px 0 rgba(0,0,0,.3)}
.hidden{display:none!important}
#app{position:fixed;inset:0;overflow:hidden;isolation:isolate;background:#05070d}
#game{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
#grain{position:absolute;inset:-50%;pointer-events:none;z-index:2;opacity:.045;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");animation:grain 7s steps(8) infinite}
@keyframes grain{0%,100%{transform:translate(0,0)}12%{transform:translate(-2%,1%)}25%{transform:translate(1%,-2%)}37%{transform:translate(-1%,2%)}50%{transform:translate(2%,1%)}62%{transform:translate(1%,2%)}75%{transform:translate(-2%,-1%)}87%{transform:translate(2%,-2%)}}
#vignette{position:absolute;inset:0;pointer-events:none;z-index:3;background:radial-gradient(ellipse at 50% 46%,transparent 38%,rgba(2,4,9,.25) 70%,rgba(2,4,9,.7) 100%)}
.glass{background:linear-gradient(145deg,rgba(20,28,46,.74),rgba(7,11,20,.82));border:1px solid var(--line);box-shadow:var(--shadow),inset 0 1px 0 rgba(255,255,255,.05);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
.eyebrow{font-size:10px;letter-spacing:.32em;text-transform:uppercase;color:var(--gold);font-weight:700}
.screen{position:absolute;inset:0;z-index:10;opacity:0;visibility:hidden;transition:opacity .55s ease,visibility .55s}
.screen.active{opacity:1;visibility:visible}
.primary-btn{display:inline-flex;align-items:center;justify-content:center;gap:14px;padding:15px 24px;border:1px solid rgba(255,232,172,.5);border-radius:2px;background:linear-gradient(135deg,#d4b46b,#9a7838);color:#16120a;font:700 13px/1 var(--sans);letter-spacing:.13em;text-transform:uppercase;box-shadow:0 8px 30px rgba(201,166,90,.2),inset 0 1px 0 rgba(255,255,255,.5);transition:.25s transform,.25s box-shadow,.25s filter}
.primary-btn:hover{transform:translateY(-2px);filter:brightness(1.1);box-shadow:0 12px 40px rgba(201,166,90,.35)}
.primary-btn span{font-size:17px}
.ghost-btn{padding:10px 16px;border:1px solid var(--line);background:rgba(255,255,255,.035);font-size:12px;letter-spacing:.08em;color:#d8d3c6;border-radius:2px;transition:.2s}
.ghost-btn:hover{border-color:var(--line-strong);background:rgba(255,255,255,.08)}
.small-btn{padding:6px 10px;border:1px solid var(--line);background:rgba(255,255,255,.04);font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--gold);border-radius:2px}

/* ============================ TITLE ============================ */
.title-screen{z-index:20;display:flex;flex-direction:column;padding:clamp(20px,3.2vw,48px) clamp(24px,5vw,80px) clamp(18px,2.8vw,38px);background:linear-gradient(90deg,rgba(4,7,14,.9) 0%,rgba(4,7,14,.63) 34%,rgba(4,7,14,.12) 62%,rgba(4,7,14,.36) 100%);pointer-events:none}
.title-screen>*{pointer-events:auto}
.title-screen::before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(2,4,10,.7),transparent 28%,transparent 68%,rgba(2,4,10,.85))}
.title-topline{display:flex;align-items:center;gap:14px;font-size:9px;letter-spacing:.24em;color:rgba(236,213,159,.62);text-transform:uppercase;font-weight:700}
.title-topline .sigil{color:var(--gold);font-size:14px;text-shadow:0 0 20px var(--gold)}
.title-topline .title-version{margin-left:auto;color:rgba(246,239,223,.4);letter-spacing:.16em}
.title-content{flex:1;display:flex;flex-direction:column;justify-content:center;max-width:620px;padding-bottom:2vh}
.title-logo{position:relative;margin:0 0 clamp(20px,3vh,40px)}
.logo-eyebrow{display:flex;align-items:center;gap:12px;font-size:9px;font-weight:700;letter-spacing:.32em;color:var(--gold-2);text-transform:uppercase;margin-bottom:12px}
.logo-eyebrow span{height:1px;width:42px;background:linear-gradient(90deg,transparent,var(--gold-2))}
.logo-eyebrow span:last-child{background:linear-gradient(90deg,var(--gold-2),transparent)}
.title-logo h1{margin:0;font-family:var(--serif);font-weight:400;line-height:.82;letter-spacing:-.02em;filter:drop-shadow(0 12px 38px rgba(0,0,0,.6))}
.title-small{display:block;font-size:clamp(30px,5.2vw,72px);letter-spacing:.26em;color:#efe8d8;text-shadow:0 2px 30px rgba(255,224,160,.2)}
.title-big{display:block;font-size:clamp(56px,10.6vw,154px);letter-spacing:.06em;line-height:.92;background:linear-gradient(180deg,#fff8e2 0%,#ead39a 34%,#b38b43 68%,#6d4d1f 100%);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:none;position:relative}
.title-big::after{content:"CELESTIAL";position:absolute;inset:0;z-index:-1;color:transparent;-webkit-text-stroke:1px rgba(255,231,172,.18);filter:blur(7px)}
.title-tagline{font-family:var(--serif);font-style:italic;font-size:clamp(12px,1.35vw,17px);color:rgba(246,239,223,.76);margin:20px 0 0;letter-spacing:.02em}
.title-rule{display:flex;align-items:center;gap:14px;width:min(100%,430px);margin:18px 0 12px;color:var(--gold-2);font-size:10px}
.title-rule i{height:1px;flex:1;background:linear-gradient(90deg,transparent,var(--line-strong));}
.title-rule i:last-child{background:linear-gradient(90deg,var(--line-strong),transparent)}
.title-lore{font-size:10px;letter-spacing:.19em;text-transform:uppercase;color:rgba(246,239,223,.45)}
.title-menu{display:flex;flex-direction:column;gap:7px;width:min(100%,390px)}
.menu-btn{display:flex;align-items:center;gap:15px;width:100%;padding:11px 15px;text-align:left;border:1px solid transparent;border-left:1px solid rgba(236,213,159,.18);background:linear-gradient(90deg,rgba(20,28,46,.48),rgba(10,15,28,.04));transition:.25s;position:relative;overflow:hidden}
.menu-btn::before{content:"";position:absolute;left:-100%;top:0;bottom:0;width:70%;background:linear-gradient(90deg,transparent,rgba(236,213,159,.08),transparent);transition:left .5s}
.menu-btn:hover::before{left:130%}
.menu-btn:hover,.menu-btn.primary{border-left-color:var(--gold);background:linear-gradient(90deg,rgba(40,48,67,.62),rgba(10,15,28,.06));transform:translateX(4px)}
.menu-btn:disabled{opacity:.34;cursor:not-allowed;transform:none!important}
.menu-ico{width:35px;height:35px;display:grid;place-items:center;border:1px solid rgba(236,213,159,.22);border-radius:50%;color:var(--gold);font-size:14px;background:rgba(236,213,159,.04);flex:none}
.menu-btn.primary .menu-ico{background:rgba(236,213,159,.13);box-shadow:0 0 24px rgba(236,213,159,.12)}
.menu-btn b{display:block;font-family:var(--serif);font-weight:400;font-size:16px;letter-spacing:.06em;color:#f3ecdb}
.menu-btn small{display:block;font-size:9px;letter-spacing:.1em;color:rgba(246,239,223,.43);margin-top:2px}
.title-footer{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;border-top:1px solid rgba(236,213,159,.1);padding-top:16px}
.title-features{display:flex;gap:24px;flex-wrap:wrap;font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:rgba(246,239,223,.4)}
.title-hint{font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:rgba(246,239,223,.45);white-space:nowrap}
.title-hint kbd{margin:0 4px}
.title-sword{position:absolute;right:7%;top:9%;bottom:11%;width:160px;pointer-events:none;opacity:.9;filter:drop-shadow(0 0 32px rgba(255,220,140,.2))}
.sword-glow{position:absolute;inset:10% -50%;background:radial-gradient(ellipse at 50% 30%,rgba(255,229,164,.16),transparent 62%);filter:blur(10px)}
.sword-blade{position:absolute;left:50%;top:2%;width:30px;height:67%;transform:translateX(-50%);clip-path:polygon(50% 0,100% 12%,100% 100%,0 100%,0 12%);background:linear-gradient(90deg,#4d3a1d,#f7e8b8 38%,#fffbea 50%,#c2a45b 68%,#453116);box-shadow:0 0 40px rgba(255,236,180,.4)}
.sword-blade::after{content:"";position:absolute;left:50%;top:4%;bottom:5%;width:2px;background:rgba(255,255,255,.9);box-shadow:0 0 14px #fff,0 0 36px #ffe9a8;transform:translateX(-50%)}
.sword-guard{position:absolute;left:50%;top:67%;width:142px;height:22px;transform:translateX(-50%);border-radius:50% 50% 4px 4px;background:linear-gradient(180deg,#f3d990,#8e6a2b 55%,#3e2c12);box-shadow:0 4px 18px rgba(0,0,0,.5),0 0 22px rgba(255,226,148,.2)}
.sword-guard::before,.sword-guard::after{content:"";position:absolute;top:7px;width:22px;height:22px;border:3px solid #c9a65a;border-radius:50%;background:#14101a}
.sword-guard::before{left:-6px}.sword-guard::after{right:-6px}
.sword-hilt{position:absolute;left:50%;top:70%;width:18px;height:24%;transform:translateX(-50%);background:repeating-linear-gradient(180deg,#3b2a1a 0 9px,#806036 9px 13px);border-radius:0 0 8px 8px;box-shadow:0 0 0 3px #20160d}
.title-sword::after{content:"";position:absolute;left:50%;top:94%;width:38px;height:38px;transform:translateX(-50%);border:4px solid #c9a65a;border-radius:50%;background:radial-gradient(circle,#f6df9d,#7b5a24 70%)}
.title-sword{animation:swordFloat 6s ease-in-out infinite}
@keyframes swordFloat{0%,100%{transform:translateY(0) rotate(1.5deg)}50%{transform:translateY(-12px) rotate(-1deg)}}

/* ============================ CREATOR ============================ */
.creator-screen{z-index:30;background:radial-gradient(ellipse at 22% 45%,rgba(39,55,78,.45),transparent 50%),linear-gradient(100deg,rgba(5,8,16,.94),rgba(6,10,18,.9) 45%,rgba(6,10,18,.96));overflow-y:auto;padding:clamp(18px,3vw,40px) clamp(20px,4vw,64px)}
.creator-header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;max-width:1500px;margin:0 auto 20px}
.creator-header h2{font-family:var(--serif);font-size:clamp(28px,3vw,44px);font-weight:400;margin:4px 0 6px;letter-spacing:.02em}
.creator-header p{margin:0;max-width:620px;color:rgba(246,239,223,.52);font-family:var(--serif);font-style:italic;font-size:13px;line-height:1.6}
.creator-layout{display:grid;grid-template-columns:minmax(300px,.82fr) minmax(520px,1.4fr);gap:clamp(18px,3vw,46px);max-width:1500px;margin:0 auto;align-items:start}
.creator-preview{position:sticky;top:20px;padding:0;overflow:hidden}
.preview-stage{position:relative;height:min(50vh,540px);background:radial-gradient(ellipse at 50% 35%,rgba(75,96,123,.33),transparent 60%),linear-gradient(180deg,#0d1524,#070a12);overflow:hidden}
.preview-stage::before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(236,213,159,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(236,213,159,.035) 1px,transparent 1px);background-size:40px 40px;mask-image:radial-gradient(ellipse at 50% 55%,#000,transparent 70%)}
.preview-stage::after{content:"";position:absolute;left:50%;bottom:7%;width:260px;height:36px;transform:translateX(-50%);background:radial-gradient(ellipse,rgba(236,213,159,.18),transparent 68%);filter:blur(8px)}
#creator-canvas{position:absolute;inset:0;width:100%;height:100%;z-index:2}
.preview-halo{position:absolute;left:50%;top:45%;width:340px;height:340px;transform:translate(-50%,-50%);border:1px solid rgba(236,213,159,.1);border-radius:50%;box-shadow:0 0 80px rgba(104,174,232,.08) inset,0 0 0 40px rgba(236,213,159,.018),0 0 0 80px rgba(236,213,159,.012);z-index:1}
.preview-caption{position:absolute;bottom:16px;left:0;right:0;text-align:center;font-size:9px;letter-spacing:.32em;color:rgba(236,213,159,.5);z-index:3}
.preview-stats{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);background:rgba(4,8,15,.7)}
.preview-stats div{padding:12px 8px;text-align:center;border-right:1px solid rgba(236,213,159,.08)}
.preview-stats div:last-child{border:0}
.preview-stats span{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.14em;color:var(--muted)}
.preview-stats b{display:block;font-family:var(--serif);font-size:18px;color:var(--gold);margin-top:2px;font-weight:400}
.preview-note{text-align:center;margin:0;padding:10px;font-size:9px;letter-spacing:.04em;color:rgba(246,239,223,.35);font-style:italic}
.creator-controls{display:flex;flex-direction:column;gap:16px;padding-bottom:30px}
.creator-section{border-top:1px solid rgba(236,213,159,.13);padding-top:14px}
.field-label{display:block;font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:var(--gold-2);margin-bottom:7px;font-weight:700}
.name-field{display:flex;align-items:center;border:1px solid rgba(236,213,159,.25);background:rgba(255,255,255,.035);padding:0 12px;border-radius:2px;max-width:420px}
.name-field input{flex:1;height:46px;border:0;background:transparent;color:var(--ivory);font-family:var(--serif);font-size:20px;letter-spacing:.04em;outline:0}
.name-field span{font-size:9px;color:var(--muted)}
.name-suggestions{display:flex;gap:6px;margin-top:7px;flex-wrap:wrap}
.name-suggestions button{font-size:9px;letter-spacing:.08em;color:var(--muted);padding:4px 8px;border:1px solid rgba(255,255,255,.08);border-radius:2px;background:rgba(255,255,255,.02)}
.name-suggestions button:hover{color:var(--gold);border-color:var(--line-strong)}
.section-title{display:flex;align-items:center;gap:10px;font-family:var(--serif);font-size:17px;letter-spacing:.04em;margin-bottom:11px}
.section-title span{font-family:var(--sans);font-size:8px;letter-spacing:.1em;color:var(--gold-2);border:1px solid rgba(236,213,159,.2);padding:3px 5px;border-radius:2px}
.section-desc{margin:-4px 0 11px;font-size:11px;color:var(--muted);line-height:1.5;max-width:650px}
.option-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 24px}
.option-group.wide{grid-column:span 2}
.option-group>label{display:block;font-size:9px;letter-spacing:.13em;text-transform:uppercase;color:rgba(246,239,223,.44);margin-bottom:5px}
.pill-row{display:flex;flex-wrap:wrap;gap:4px}
.pill{padding:6px 10px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.025);font-size:10px;color:#a9a495;border-radius:2px;transition:.18s}
.pill:hover{border-color:rgba(236,213,159,.3);color:#e6dfcf}
.pill.active{border-color:rgba(236,213,159,.55);background:rgba(236,213,159,.12);color:var(--gold);box-shadow:0 0 20px rgba(236,213,159,.06) inset}
.swatches{display:flex;gap:7px;flex-wrap:wrap}
.swatch{width:29px;height:29px;border-radius:50%;border:2px solid transparent;background:linear-gradient(135deg,#d8c39d,#836b48);position:relative;transition:.18s;box-shadow:0 2px 8px rgba(0,0,0,.3)}
.swatch.face-b{background:linear-gradient(135deg,#c9a078,#7b523c)}
.swatch.face-c{background:linear-gradient(135deg,#f1c9ad,#a97658)}
.swatch.active{border-color:var(--gold);box-shadow:0 0 0 2px rgba(236,213,159,.2),0 0 16px rgba(236,213,159,.3)}
.swatch[style*="--c"]{background:var(--c)}
.swatch[style*="--c"]::after{content:"";position:absolute;inset:3px;border-radius:50%;border:1px solid rgba(0,0,0,.2)}
.boon-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}
.boon{display:flex;flex-direction:column;align-items:flex-start;gap:3px;padding:11px 10px;border:1px solid rgba(255,255,255,.1);background:linear-gradient(150deg,rgba(255,255,255,.035),rgba(255,255,255,.01));text-align:left;border-radius:2px;transition:.2s}
.boon span{color:var(--gold-2);font-size:14px}
.boon b{font-size:11px;letter-spacing:.04em;color:#e8e1d2}
.boon small{font-size:8px;line-height:1.5;color:var(--muted)}
.boon:hover{border-color:rgba(236,213,159,.3);transform:translateY(-1px)}
.boon.active{border-color:rgba(236,213,159,.55);background:linear-gradient(150deg,rgba(236,213,159,.14),rgba(236,213,159,.025));box-shadow:0 8px 28px rgba(0,0,0,.2)}
.creator-actions{display:flex;align-items:center;justify-content:space-between;gap:20px;border-top:1px solid var(--line);padding-top:16px}
.creator-warning{font-size:9px;color:rgba(246,239,223,.35);max-width:280px;line-height:1.5}

/* ============================ HUD ============================ */
#hud{position:absolute;inset:0;z-index:8;pointer-events:none;padding:clamp(10px,1.5vw,22px);display:flex;flex-direction:column;justify-content:space-between}
#hud button{pointer-events:auto}
.hud-top{display:flex;align-items:flex-start;gap:12px;justify-content:space-between}
.player-card{display:flex;gap:10px;padding:9px 12px 9px 9px;border-radius:4px;width:min(330px,27vw);min-width:250px;position:relative}
.portrait-wrap{position:relative;width:56px;height:56px;flex:none}
#hud-portrait{width:56px;height:56px;border-radius:50%;border:1px solid rgba(236,213,159,.4);background:radial-gradient(circle at 50% 30%,#354b67,#0b101c);box-shadow:0 0 22px rgba(104,174,232,.16)}
.level-badge{position:absolute;right:-4px;bottom:-2px;min-width:20px;height:20px;border-radius:50%;background:linear-gradient(135deg,#e9d299,#8c6a2d);color:#151008;display:grid;place-items:center;font-size:9px;font-weight:800;border:1px solid #2b2110}
.player-vitals{flex:1;min-width:0}
.player-name-row{display:flex;align-items:baseline;gap:7px;margin-bottom:4px;white-space:nowrap;overflow:hidden}
.player-name-row strong{font-family:var(--serif);font-weight:400;font-size:15px;letter-spacing:.04em}
.player-title{font-size:7px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bar{height:7px;position:relative;border-radius:1px;background:rgba(0,0,0,.55);margin-bottom:3px;overflow:hidden;border:1px solid rgba(255,255,255,.06)}
.bar i{display:block;height:100%;width:100%;transition:width .25s ease;position:relative}
.bar i::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.22),transparent 60%)}
.bar span{position:absolute;inset:0;text-align:center;font-size:7px;line-height:7px;font-weight:700;color:rgba(255,255,255,.8);text-shadow:0 1px 2px #000}
.bar.hp i{background:linear-gradient(90deg,#8e2f38,#d85f62)}
.bar.mana{height:5px}.bar.mana i{background:linear-gradient(90deg,#2f5c8e,#68aee8)}
.bar.stamina{height:4px}.bar.stamina i{background:linear-gradient(90deg,#8e792f,#d8c065)}
.xp-row{display:flex;align-items:center;gap:5px;font-size:7px;color:var(--muted);margin-top:2px;text-transform:uppercase;letter-spacing:.05em}
.xp-row b{color:#e6dfcf}
.xp-bar{flex:1;height:3px;background:rgba(0,0,0,.55);overflow:hidden}
.xp-bar i{display:block;height:100%;background:linear-gradient(90deg,#7ec8e3,#b69cff);transition:width .3s}
#hud-gold{color:var(--gold);white-space:nowrap}
.quest-card{width:min(370px,30vw);padding:10px 14px;border-radius:4px;border-left:2px solid var(--gold-2);align-self:flex-start}
.quest-kicker{font-size:7px;letter-spacing:.2em;color:var(--gold-2);display:flex;align-items:center;gap:6px;text-transform:uppercase}
.diamond{width:5px;height:5px;background:var(--gold);transform:rotate(45deg);display:inline-block;box-shadow:0 0 8px var(--gold)}
.quest-card h3{font-family:var(--serif);font-weight:400;font-size:14px;margin:4px 0 2px;letter-spacing:.02em}
.quest-card p{margin:0;font-size:9px;line-height:1.4;color:rgba(246,239,223,.58)}
.quest-distance{display:flex;justify-content:space-between;margin-top:5px;font-size:8px;letter-spacing:.09em;color:var(--gold);text-transform:uppercase}
.compass{font-size:11px}
.map-card{width:min(250px,22vw);padding:8px;border-radius:4px;align-self:flex-start}
.region-line{display:flex;justify-content:space-between;font-size:7px;letter-spacing:.17em;text-transform:uppercase;color:var(--gold-2);margin:0 2px 5px}
#hud-time{color:rgba(246,239,223,.45)}
#minimap{width:100%;height:auto;display:block;border:1px solid rgba(236,213,159,.1);background:#0a101c}
.map-legend{display:flex;gap:8px;font-size:6px;letter-spacing:.06em;text-transform:uppercase;color:rgba(246,239,223,.4);margin-top:4px}
.map-legend span{display:flex;align-items:center;gap:3px}
.dot{width:4px;height:4px;border-radius:50%;display:inline-block}
.dot.you{background:#fff}.dot.obj{background:var(--gold);box-shadow:0 0 4px var(--gold)}.dot.npc{background:var(--blue)}
.hud-bottom{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;position:relative}
.bottom-left{display:flex;flex-direction:column;gap:6px;align-items:flex-start}
.party-card{padding:6px 9px;border-radius:3px}
.party-label{font-size:6px;letter-spacing:.2em;color:var(--gold-2);margin-bottom:3px;text-transform:uppercase}
.party-slots{display:flex;gap:5px}
.party-slot{width:29px;height:29px;border:1px solid rgba(236,213,159,.18);border-radius:50%;background:rgba(0,0,0,.3);display:grid;place-items:center;position:relative;overflow:hidden}
.party-slot canvas{width:100%;height:100%}
.party-slot.empty{color:rgba(246,239,223,.16);font-size:11px}
.party-slot.active{border-color:var(--gold);box-shadow:0 0 12px rgba(236,213,159,.25)}
.party-slot .key{position:absolute;right:-1px;bottom:-1px;background:#0a0e18;font-size:5px;width:9px;height:9px;display:grid;place-items:center;border-radius:50%;color:var(--gold)}
.status-icons{display:flex;gap:3px}
.status-pill{padding:3px 6px;border:1px solid rgba(255,255,255,.12);background:rgba(0,0,0,.45);font-size:6px;letter-spacing:.08em;text-transform:uppercase;color:var(--gold);border-radius:2px}
.interact-prompt{position:absolute;left:50%;bottom:8px;transform:translateX(-50%);display:flex;align-items:center;gap:7px;padding:7px 11px;background:rgba(6,10,18,.82);border:1px solid rgba(236,213,159,.24);border-radius:3px;font-size:9px;letter-spacing:.08em;color:#ece6d6;backdrop-filter:blur(6px);animation:promptPulse 2s infinite}
@keyframes promptPulse{0%,100%{border-color:rgba(236,213,159,.24)}50%{border-color:rgba(236,213,159,.6)}}
.hud-actions{display:flex;flex-direction:column;align-items:flex-end;gap:6px}
.key-hints{display:flex;flex-wrap:wrap;gap:4px 9px;justify-content:flex-end;max-width:600px;font-size:7px;letter-spacing:.05em;color:rgba(246,239,223,.4);text-transform:uppercase}
.key-hints span{display:flex;align-items:center;gap:4px;white-space:nowrap}
.key-hints kbd{height:15px;min-width:15px;font-size:7px;padding:0 3px;color:rgba(246,239,223,.65)}
.touch-controls{display:none;width:100%;justify-content:space-between;align-items:flex-end}
.touch-controls:not(.hidden){display:flex}
.joystick{width:112px;height:112px;position:relative;border-radius:50%;border:1px solid rgba(236,213,159,.22);background:radial-gradient(circle,rgba(236,213,159,.08),rgba(0,0,0,.2));touch-action:none;pointer-events:auto;margin-bottom:2px}
.joystick-base{position:absolute;inset:26px;border:1px solid rgba(236,213,159,.12);border-radius:50%}
.joystick-knob{position:absolute;width:46px;height:46px;left:33px;top:33px;border-radius:50%;background:radial-gradient(circle at 40% 35%,rgba(255,240,199,.5),rgba(150,120,60,.4));border:1px solid rgba(236,213,159,.5);box-shadow:0 4px 14px rgba(0,0,0,.4),0 0 18px rgba(236,213,159,.15)}
.touch-buttons{display:grid;grid-template-columns:repeat(3,54px);grid-template-rows:repeat(2,54px);gap:7px;align-items:end;pointer-events:auto}
.tbtn{width:54px;height:54px;border-radius:50%;border:1px solid rgba(236,213,159,.25);background:rgba(10,15,27,.6);display:flex;flex-direction:column;align-items:center;justify-content:center;color:#e8e1d2;backdrop-filter:blur(5px);pointer-events:auto;touch-action:none}
.tbtn span{font-size:17px;line-height:1;color:var(--gold)}
.tbtn small{font-size:5px;letter-spacing:.05em;margin-top:2px;color:rgba(246,239,223,.6);text-transform:uppercase}
.tbtn.attack{width:68px;height:68px;grid-column:3;grid-row:2;margin-left:-7px;border-color:rgba(236,213,159,.45);background:radial-gradient(circle at 40% 35%,rgba(236,213,159,.18),rgba(10,15,27,.7))}
.tbtn.attack span{font-size:24px}
.tbtn.dodge{grid-column:2;grid-row:2}
.tbtn.block{grid-column:1;grid-row:2}
.tbtn.skill{grid-column:2;grid-row:1}
.tbtn.resonance{grid-column:1;grid-row:1}
.tbtn.creature{grid-column:3;grid-row:1}
.tbtn.interact{grid-column:1;grid-row:2;opacity:.8}
.tbtn:active{transform:scale(.92);background:rgba(236,213,159,.2)}
.boss-bar{position:absolute;left:50%;top:16px;transform:translateX(-50%);width:min(600px,60vw);padding:7px 12px;background:linear-gradient(90deg,rgba(7,10,18,.15),rgba(7,10,18,.8),rgba(7,10,18,.15));border-top:1px solid rgba(236,213,159,.2);border-bottom:1px solid rgba(236,213,159,.2);text-align:center;z-index:4}
.boss-heading{display:flex;align-items:baseline;justify-content:center;gap:10px}
#boss-name{font-family:var(--serif);font-size:16px;letter-spacing:.1em;color:#f3e6c9}
#boss-sub{font-size:6px;letter-spacing:.2em;color:var(--red);text-transform:uppercase}
.boss-track{height:8px;background:#0a0a0f;border:1px solid rgba(236,213,159,.22);margin-top:4px;position:relative;overflow:hidden}
.boss-track i{display:block;height:100%;background:linear-gradient(90deg,#7d232c,#d85f62,#e8a66a);transition:width .3s}
.boss-track b{position:absolute;inset:0;background:rgba(255,255,255,.35);transform-origin:left;transition:transform 1.2s .25s;opacity:.25}
.boss-phases{display:flex;justify-content:center;gap:3px;margin-top:3px}
.boss-phases span{width:30px;height:2px;background:rgba(236,213,159,.2)}
.boss-phases span.on{background:var(--gold)}
.toasts{position:absolute;left:50%;top:18%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:5px;pointer-events:none;z-index:15;width:min(440px,80vw)}
.toast{padding:7px 15px;background:linear-gradient(90deg,rgba(9,14,25,.2),rgba(9,14,25,.92),rgba(9,14,25,.2));border-top:1px solid rgba(236,213,159,.22);border-bottom:1px solid rgba(236,213,159,.22);font-size:10px;letter-spacing:.06em;color:#f1e9d8;text-align:center;animation:toastIn .4s ease both;text-shadow:0 2px 6px #000}
.toast.gold{color:var(--gold);border-color:rgba(236,213,159,.4)}
.toast.danger{color:#ff9b9b;border-color:rgba(216,95,98,.4)}
.toast.blue{color:#a7d8ef;border-color:rgba(104,174,232,.35)}
.toast.out{animation:toastOut .4s ease both}
@keyframes toastIn{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:translateY(0)}}
@keyframes toastOut{to{opacity:0;transform:translateY(-8px)}}
.area-banner{position:absolute;left:0;right:0;top:34%;text-align:center;pointer-events:none;animation:areaIn 4.5s ease both}
.area-banner span{font-size:8px;letter-spacing:.45em;color:var(--gold-2);text-transform:uppercase}
.area-banner h2{font-family:var(--serif);font-weight:400;font-size:clamp(36px,6vw,76px);letter-spacing:.2em;margin:5px 0;color:#f4ead3;text-shadow:0 0 40px rgba(236,213,159,.3),0 4px 20px #000}
.area-banner p{font-family:var(--serif);font-style:italic;color:rgba(246,239,223,.58);font-size:12px;letter-spacing:.08em;margin:0}
@keyframes areaIn{0%{opacity:0;transform:scale(1.05)}15%,72%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.99)}}
.damage-layer{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:7}
.dmg{position:absolute;font-family:var(--serif);font-weight:700;font-size:18px;color:#fff;text-shadow:0 2px 5px #000;animation:dmgFloat 1s ease-out forwards;white-space:nowrap}
.dmg.crit{color:#ffd76e;font-size:25px;text-shadow:0 0 14px rgba(255,215,110,.7),0 2px 4px #000}
.dmg.heal{color:#8ce8a9}.dmg.mana{color:#8cc8ff}
@keyframes dmgFloat{0%{opacity:0;transform:translate(-50%,0) scale(.7)}15%{opacity:1;transform:translate(-50%,-12px) scale(1.1)}100%{opacity:0;transform:translate(-50%,-55px) scale(.9)}}

/* ============================ CINEMATIC / DIALOGUE ============================ */
.cinematic{z-index:50;position:absolute;inset:0;background:linear-gradient(180deg,rgba(2,4,9,.15),rgba(2,4,9,.05) 40%,rgba(2,4,9,.85));pointer-events:auto}
.cine-bars{position:absolute;left:0;right:0;height:10vh;background:#020308;z-index:2}
.cine-bars.top{top:0;border-bottom:1px solid rgba(236,213,159,.1)}.cine-bars.bottom{bottom:0;border-top:1px solid rgba(236,213,159,.1)}
.cine-caption{position:absolute;left:8%;right:8%;bottom:16%;z-index:3;text-align:center;max-width:900px;margin:auto}
#cine-kicker{font-size:9px;letter-spacing:.4em;color:var(--gold);text-transform:uppercase;display:block;margin-bottom:10px}
#cine-text{font-family:var(--serif);font-size:clamp(18px,2.6vw,34px);line-height:1.45;letter-spacing:.03em;color:#f2ead8;text-shadow:0 3px 22px #000;margin:0;min-height:1.5em}
.cine-skip{position:absolute;right:5%;top:12%;z-index:4;font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:rgba(246,239,223,.45);padding:6px 10px;border:1px solid rgba(255,255,255,.12);background:rgba(0,0,0,.25)}
.cine-skip:hover{color:var(--gold);border-color:var(--line-strong)}
.cine-continue{position:absolute;left:0;right:0;bottom:12.5%;z-index:3;text-align:center;font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:rgba(246,239,223,.35)}
.dialogue{z-index:45;position:absolute;left:0;right:0;bottom:0;display:flex;align-items:flex-end;justify-content:center;gap:0;padding:0 clamp(16px,4vw,70px) clamp(16px,3.2vh,34px);pointer-events:auto;background:linear-gradient(0deg,rgba(2,4,10,.7),transparent 75%)}
.dialogue-portrait-wrap{position:relative;width:clamp(100px,13vw,160px);height:clamp(100px,13vw,160px);flex:none;margin-right:-22px;margin-bottom:8px;z-index:2}
#dialogue-portrait{width:100%;height:100%;border-radius:50%;background:radial-gradient(circle at 50% 35%,#334b63,#090d16);border:1px solid rgba(236,213,159,.4);box-shadow:0 0 40px rgba(0,0,0,.8),0 0 0 7px rgba(7,10,18,.85),0 0 0 8px rgba(236,213,159,.18)}
.portrait-ring{position:absolute;inset:-10px;border:1px solid rgba(236,213,159,.12);border-radius:50%;border-top-color:rgba(236,213,159,.5);animation:spin 14s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.dialogue-panel{width:min(900px,80vw);padding:17px 24px 15px;border-radius:2px;border-left:2px solid var(--gold-2);min-height:130px;position:relative}
.dialogue-name-row{display:flex;align-items:baseline;gap:10px;margin-bottom:6px}
.dialogue-name-row h3{font-family:var(--serif);font-weight:400;font-size:20px;letter-spacing:.04em;margin:0;color:#f5edda}
#dialogue-role{font-size:7px;letter-spacing:.18em;text-transform:uppercase;color:var(--gold-2)}
#dialogue-text{font-family:var(--serif);font-size:clamp(13px,1.35vw,16px);line-height:1.65;color:rgba(246,239,223,.83);margin:0;min-height:44px;max-width:780px}
.dialogue-next{position:absolute;right:18px;bottom:10px;color:var(--gold);font-size:10px;animation:bob 1.4s infinite}
@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(4px)}}
.dialogue-choices{display:flex;flex-direction:column;gap:4px;margin-top:10px;max-width:620px}
.dialogue-choice{text-align:left;padding:7px 12px;border:1px solid rgba(236,213,159,.16);background:rgba(236,213,159,.035);font-size:11px;color:#ded7c7;transition:.18s}
.dialogue-choice:hover,.dialogue-choice.selected{border-color:var(--gold-2);background:rgba(236,213,159,.11);color:#fff}
.dialogue-choice b{color:var(--gold);margin-right:7px;font-size:9px}

/* ============================ PANEL SCREENS ============================ */
.panel-screen{z-index:40;background:rgba(3,6,12,.72);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);padding:clamp(8px,2.2vh,22px) clamp(8px,2.5vw,34px);display:flex;align-items:center;justify-content:center}
.panel-shell{width:min(1380px,96vw);height:min(870px,94vh);display:flex;flex-direction:column;background:linear-gradient(145deg,rgba(13,20,35,.98),rgba(6,9,17,.99));border:1px solid rgba(236,213,159,.22);box-shadow:0 40px 120px rgba(0,0,0,.8);position:relative}
.panel-shell::before{content:"";position:absolute;inset:5px;border:1px solid rgba(236,213,159,.05);pointer-events:none}
.panel-header{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:16px 24px;border-bottom:1px solid rgba(236,213,159,.15)}
.panel-header h2{font-family:var(--serif);font-weight:400;font-size:26px;letter-spacing:.03em;margin:2px 0 0}
.panel-header-right{display:flex;align-items:center;gap:16px;font-size:9px;letter-spacing:.1em;color:var(--muted);text-transform:uppercase}
.close-panel{width:30px;height:30px;border:1px solid rgba(255,255,255,.15);color:#cfc7b6;font-size:12px}
.close-panel:hover{border-color:var(--gold);color:var(--gold)}
.pause-layout{display:flex;flex:1;min-height:0}
.pause-nav{width:190px;flex:none;border-right:1px solid rgba(236,213,159,.12);padding:16px 10px;display:flex;flex-direction:column;gap:3px}
.pause-nav button{display:flex;align-items:center;gap:10px;padding:9px 12px;text-align:left;border-left:1px solid transparent;font-size:11px;color:rgba(246,239,223,.56);transition:.18s;letter-spacing:.04em}
.pause-nav button span{font-size:10px;text-transform:uppercase;letter-spacing:.1em}
.pause-nav button:hover{background:rgba(255,255,255,.04);color:#eee5d3}
.pause-nav button.active{border-left-color:var(--gold);background:linear-gradient(90deg,rgba(236,213,159,.11),transparent);color:var(--gold)}
.pause-nav .save-btn{margin-top:auto;border:1px solid rgba(236,213,159,.22);justify-content:center;color:var(--gold);font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.pause-nav .quit-btn{border:1px solid rgba(255,255,255,.08);justify-content:center;font-size:9px;text-transform:uppercase;color:rgba(246,239,223,.4)}
.pause-content{flex:1;overflow-y:auto;padding:20px 24px;scrollbar-width:thin;scrollbar-color:#6b5a38 #0a0f1a}
.tab-pane{display:none;animation:fadeIn .25s ease}
.tab-pane.active{display:block}
@keyframes fadeIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
.pane-title{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:15px}
.pane-title h3{font-family:var(--serif);font-weight:400;font-size:22px;margin:0}
.pane-title p{margin:0;font-size:10px;color:var(--muted);font-family:var(--serif);font-style:italic}
.hero-sheet{display:grid;grid-template-columns:250px 1fr;gap:22px}
.hero-art{border:1px solid var(--line);position:relative;overflow:hidden;min-height:330px;background:radial-gradient(ellipse at 50% 40%,rgba(65,83,111,.3),rgba(6,9,16,.8))}
#sheet-portrait{width:100%;height:100%;position:absolute;inset:0}
.hero-art-label{position:absolute;left:0;right:0;bottom:0;padding:12px;background:linear-gradient(0deg,rgba(5,8,14,.9),transparent);text-align:center}
.hero-art-label span{display:block;font-family:var(--serif);font-size:20px}
.hero-art-label small{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-2)}
.stat-header{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase;margin-bottom:4px}
.stat-header b{color:var(--gold);font-size:14px}
.xp-bar.big{height:5px;background:rgba(0,0,0,.5);margin-bottom:14px}
.xp-bar.big i{background:linear-gradient(90deg,#68aee8,#b69cff)}
.stat-list{display:grid;grid-template-columns:1fr 1fr;gap:5px 20px;margin-bottom:10px}
.stat-row{display:flex;align-items:center;justify-content:space-between;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.05);font-size:11px}
.stat-row>span{color:rgba(246,239,223,.62);display:flex;align-items:center;gap:6px}
.stat-row .stat-val{font-family:var(--serif);font-size:16px;color:#f1e7d0;min-width:30px;text-align:right}
.stat-row .stat-plus{width:18px;height:18px;border:1px solid rgba(236,213,159,.3);color:var(--gold);display:grid;place-items:center;font-size:12px;line-height:1;border-radius:2px}
.stat-row .stat-plus:hover{background:rgba(236,213,159,.15)}
.stat-row .stat-plus.disabled{opacity:.2;pointer-events:none}
.points-row{display:flex;align-items:center;justify-content:space-between;font-size:10px;color:var(--muted);margin:8px 0}
.points-row b{color:var(--gold);font-size:13px}
.derived-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
.derived-grid div{padding:7px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);text-align:center}
.derived-grid span{display:block;font-size:7px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.derived-grid b{font-family:var(--serif);font-size:14px;font-weight:400;color:var(--gold)}
.hero-bottom{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-top:14px}
.equipment-slots{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}
.equip-slot{padding:9px;border:1px solid rgba(236,213,159,.13);background:rgba(255,255,255,.025);min-height:68px;cursor:pointer;transition:.18s}
.equip-slot:hover{border-color:rgba(236,213,159,.35);background:rgba(236,213,159,.05)}
.equip-slot span{display:block;font-size:6px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold-2);margin-bottom:4px}
.equip-slot b{display:block;font-size:10px;color:#e8e0d0;line-height:1.3}
.equip-slot small{font-size:8px;color:var(--green)}
.traits-card{padding:10px 12px}
.traits-card h4,.equipment-slots h4{margin:0 0 7px;font-size:8px;letter-spacing:.15em;text-transform:uppercase;color:var(--gold-2);font-weight:700}
.trait{display:flex;gap:7px;font-size:9px;color:rgba(246,239,223,.6);margin-bottom:5px;line-height:1.4}
.trait b{color:var(--gold);font-weight:600;white-space:nowrap}
.quest-columns{display:grid;grid-template-columns:1fr 1fr;gap:22px}
.quest-columns h4{font-size:8px;letter-spacing:.18em;text-transform:uppercase;color:var(--gold-2);margin:0 0 8px}
.quest-entry{border:1px solid rgba(255,255,255,.07);border-left:2px solid rgba(236,213,159,.3);background:rgba(255,255,255,.025);padding:10px 12px;margin-bottom:7px}
.quest-entry.done{border-left-color:var(--green);opacity:.65}
.quest-entry.active{border-left-color:var(--gold);background:linear-gradient(90deg,rgba(236,213,159,.08),transparent)}
.quest-entry h5{font-family:var(--serif);font-weight:400;font-size:13px;margin:0 0 3px;color:#eee5d3}
.quest-entry p{font-size:9px;line-height:1.5;color:var(--muted);margin:0}
.quest-entry .q-reward{font-size:8px;color:var(--gold-2);margin-top:4px;letter-spacing:.05em}
.creature-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(116px,1fr));gap:7px}
.creature-card{position:relative;border:1px solid rgba(255,255,255,.08);background:linear-gradient(160deg,rgba(255,255,255,.045),rgba(255,255,255,.01));padding:7px;text-align:center;cursor:pointer;transition:.18s;min-height:142px}
.creature-card:hover{border-color:rgba(236,213,159,.4);transform:translateY(-2px)}
.creature-card.locked{filter:grayscale(1);opacity:.32}
.creature-card.locked .c-name{color:#777}
.creature-card canvas{width:84px;height:84px;display:block;margin:0 auto}
.creature-card .c-name{font-family:var(--serif);font-size:11px;color:#eee6d4;display:block;margin-top:1px}
.creature-card .c-elem{font-size:6px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold-2)}
.creature-card .c-star{position:absolute;top:5px;right:6px;font-size:6px;color:var(--gold)}
.creature-detail{position:absolute;inset:auto 24px 20px 214px;background:rgba(7,11,20,.98);border:1px solid var(--line-strong);padding:16px;z-index:5;box-shadow:0 -20px 60px rgba(0,0,0,.6);display:grid;grid-template-columns:100px 1fr;gap:15px}
.creature-detail canvas{width:100px;height:100px}
.creature-detail h3{font-family:var(--serif);font-weight:400;margin:0;font-size:22px}
.creature-detail .cd-sub{font-size:7px;letter-spacing:.16em;color:var(--gold-2);text-transform:uppercase}
.creature-detail p{font-size:10px;line-height:1.55;color:var(--muted);margin:6px 0}
.creature-detail .cd-stats{display:flex;gap:12px;font-size:9px;color:var(--gold)}
.inventory-layout{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.inventory-layout h4{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-2);margin:0 0 7px}
.inventory-list{display:flex;flex-direction:column;gap:5px}
.inv-item{padding:8px 9px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.025);display:flex;justify-content:space-between;gap:8px;font-size:9px;align-items:center;cursor:pointer;transition:.18s}
.inv-item:hover{border-color:rgba(236,213,159,.35);background:rgba(236,213,159,.05)}
.inv-item b{display:block;font-size:10px;font-weight:500;color:#e9e1d0}
.inv-item small{font-size:7px;color:var(--muted)}
.inv-item .inv-count{color:var(--gold);font-size:9px;white-space:nowrap}
.inv-item.equipped{border-color:rgba(236,213,159,.4)}
.world-map-wrap{position:relative;border:1px solid rgba(236,213,159,.15);background:#070b13;overflow:hidden}
#world-map{width:100%;height:auto;display:block}
.map-tooltip{position:absolute;left:50%;bottom:10px;transform:translateX(-50%);padding:5px 10px;background:rgba(7,11,20,.9);border:1px solid var(--line);font-size:8px;letter-spacing:.08em;color:var(--muted)}
.region-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:8px}
.region-card{padding:8px 10px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.02);cursor:pointer;transition:.18s}
.region-card:hover{border-color:rgba(236,213,159,.3)}
.region-card b{display:block;font-family:var(--serif);font-weight:400;font-size:13px;color:#e9e1d0}
.region-card small{font-size:7px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.region-card.locked{opacity:.35}
.options-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}
.option-block{display:flex;flex-direction:column;gap:11px}
.option-block label{display:block;font-size:10px;color:var(--muted);letter-spacing:.04em}
.option-block input[type=range]{width:100%;accent-color:var(--gold-2);margin-top:5px}
.toggle-row{display:flex!important;justify-content:space-between;align-items:center;padding:8px 10px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.02)}
.toggle-row input{accent-color:var(--gold-2)}
.accessibility-note{padding:12px;border:1px solid rgba(236,213,159,.12);background:rgba(236,213,159,.03)}
.accessibility-note h4{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);margin:0 0 5px}
.accessibility-note p{font-size:9px;line-height:1.55;color:var(--muted);margin:0 0 6px}

/* ============================ ENDING ============================ */
.ending-screen{z-index:60;background:radial-gradient(ellipse at 50% 30%,rgba(62,84,111,.4),transparent 55%),linear-gradient(180deg,rgba(3,5,11,.92),rgba(4,7,14,.98));display:grid;place-items:center;padding:30px}
.ending-inner{max-width:720px;text-align:center}
.ending-eyebrow{font-size:9px;letter-spacing:.5em;color:var(--gold);text-transform:uppercase;margin-bottom:12px}
.ending-inner h1{font-family:var(--serif);font-weight:400;font-size:clamp(44px,7vw,90px);margin:0 0 12px;background:linear-gradient(180deg,#fff7df,#c8a45b);-webkit-background-clip:text;background-clip:text;color:transparent}
#ending-text{font-family:var(--serif);font-size:14px;line-height:1.8;color:rgba(246,239,223,.7);margin:0 auto 20px;max-width:620px}
.ending-stats{display:flex;justify-content:center;gap:25px;margin-bottom:25px}
.ending-stats div{text-align:center}
.ending-stats span{display:block;font-size:7px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.ending-stats b{font-family:var(--serif);font-size:22px;font-weight:400;color:var(--gold)}
.ending-actions{display:flex;justify-content:center;gap:10px}

/* ============================ MISC ============================ */
.loading{position:fixed;inset:0;z-index:100;background:#05070d;display:grid;place-items:center;gap:12px;transition:opacity .6s;pointer-events:none}
.loading.done{opacity:0}
.loading-sword{font-size:40px;color:var(--gold);animation:pulse 1.5s infinite}
.loading span{font-size:8px;letter-spacing:.4em;color:var(--gold-2)}
@keyframes pulse{0%,100%{opacity:.4;transform:scale(.95)}50%{opacity:1;transform:scale(1.1);text-shadow:0 0 30px var(--gold)}}
#rotate-hint{display:none;position:fixed;inset:0;z-index:200;background:#05070d;color:var(--ivory);text-align:center;flex-direction:column;align-items:center;justify-content:center;gap:6px}
#rotate-hint span{font-size:50px;color:var(--gold);animation:rotateHint 2s infinite}
#rotate-hint p{font-family:var(--serif);font-size:24px;margin:8px 0 0}
#rotate-hint small{font-size:10px;color:var(--muted);letter-spacing:.1em}
@keyframes rotateHint{0%,100%{transform:rotate(0)}50%{transform:rotate(90deg)}}
@media (orientation:portrait) and (max-width:900px){#rotate-hint{display:flex}}
.high-contrast{--line:rgba(255,255,255,.3);--line-strong:rgba(255,255,255,.65);--muted:#d1cbc0}
.high-contrast .glass{background:rgba(4,7,14,.95)}
.high-contrast .quest-card p,.high-contrast .player-title{color:#e5ded0}
.reduced-motion *{animation-duration:.001s!important;transition-duration:.001s!important}

/* ============================ RESPONSIVE ============================ */
@media (max-width:1050px){
  .title-sword{right:2%;opacity:.55;width:120px}
  .creator-layout{grid-template-columns:minmax(260px,.7fr) minmax(420px,1.3fr);gap:20px}
  .player-card{width:290px;min-width:0}
  .quest-card{width:300px}
  .map-card{width:190px}
  .key-hints span:nth-child(n+6){display:none}
}
@media (max-width:780px){
  .title-screen{padding:16px 20px 14px;background:linear-gradient(180deg,rgba(4,7,14,.6),rgba(4,7,14,.55) 50%,rgba(4,7,14,.92))}
  .title-topline .title-version{display:none}
  .title-content{max-width:100%;justify-content:flex-end;padding-bottom:10px}
  .title-logo{margin-bottom:12px}
  .title-big{font-size:clamp(52px,15vw,110px)}
  .title-small{font-size:clamp(24px,7vw,48px)}
  .title-tagline{font-size:11px;margin-top:12px}
  .title-rule{margin:10px 0 7px}.title-lore{font-size:8px}
  .title-menu{width:100%;gap:5px}
  .menu-btn{padding:8px 11px}.menu-btn b{font-size:14px}.menu-btn small{font-size:8px}
  .menu-ico{width:30px;height:30px}
  .title-footer{padding-top:8px}.title-features{display:none}
  .title-sword{display:none}
  .creator-screen{padding:14px}
  .creator-layout{grid-template-columns:1fr;gap:14px}
  .creator-preview{position:relative;top:0;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:auto auto}
  .preview-stage{height:230px;grid-row:span 2}
  .preview-stats{grid-template-columns:1fr 1fr;border-top:0}
  .preview-stats div{padding:8px 4px;border-bottom:1px solid rgba(236,213,159,.08)}
  .preview-note{display:none}
  .creator-header p{display:none}
  .option-grid{grid-template-columns:1fr}
  .option-group.wide{grid-column:span 1}
  .boon-grid{grid-template-columns:1fr 1fr}
  .creator-actions{flex-direction:column;align-items:stretch}.creator-warning{max-width:none}
  .hud-top{gap:5px}
  .player-card{width:210px;min-width:0;padding:6px}
  .portrait-wrap{width:40px;height:40px}.portrait-wrap canvas{width:40px!important;height:40px!important}
  .player-name-row strong{font-size:12px}.player-title{display:none}
  .bar{height:5px}.bar span{display:none}
  .quest-card{width:180px;padding:6px 8px}.quest-card h3{font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.quest-card p{font-size:7px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.quest-kicker{font-size:6px}
  .map-card{display:none}
  .key-hints{display:none}
  .touch-controls{display:flex!important}
  .hud-actions{width:100%}
  .dialogue{padding:0 8px 10px}.dialogue-panel{width:100%;padding:12px 14px;min-height:100px}.dialogue-portrait-wrap{display:none}
  .dialogue-name-row h3{font-size:16px}#dialogue-text{font-size:12px;min-height:38px}
  .panel-screen{padding:0}.panel-shell{width:100vw;height:100dvh;border:0}.panel-header{padding:10px 14px}.panel-header h2{font-size:20px}.panel-header-right span{display:none}
  .pause-nav{width:66px;padding:8px 4px}.pause-nav button{justify-content:center;padding:10px 4px}.pause-nav button span{display:none}.pause-nav .save-btn,.pause-nav .quit-btn{font-size:7px;padding:7px 2px;text-align:center}
  .pause-content{padding:12px}
  .hero-sheet{grid-template-columns:1fr}.hero-art{min-height:180px;height:180px}.stat-list{grid-template-columns:1fr 1fr}
  .hero-bottom{grid-template-columns:1fr}
  .derived-grid{grid-template-columns:repeat(2,1fr)}
  .quest-columns,.inventory-layout,.options-grid{grid-template-columns:1fr}
  .creature-grid{grid-template-columns:repeat(3,1fr)}
  .creature-detail{inset:auto 10px 10px 10px;grid-template-columns:70px 1fr}
  .region-cards{grid-template-columns:1fr}
  .ending-stats{gap:12px;flex-wrap:wrap}
  .boss-bar{width:74vw;top:66px}
}
@media (max-width:520px){
  .title-big{font-size:15vw}.title-tagline{display:none}.logo-eyebrow{font-size:7px}
  .title-menu .menu-btn:nth-child(3),.title-menu .menu-btn:nth-child(4){display:none}
  .creator-preview{grid-template-columns:1fr}.preview-stage{grid-row:auto;height:190px}.preview-stats{grid-template-columns:repeat(4,1fr)}
  .player-card{width:190px}.quest-card{width:150px}.quest-card p{display:none}
  .boss-bar{width:80vw}
  .touch-buttons{grid-template-columns:repeat(3,48px);grid-template-rows:repeat(2,48px);gap:5px}.tbtn{width:48px;height:48px}.tbtn.attack{width:60px;height:60px}
  .joystick{width:94px;height:94px}.joystick-knob{width:40px;height:40px;left:27px;top:27px}
}
