.dialogue-choice:hover,.dialogue-choice.selected{border-color:var(--gold-2);background:rgba(236,213,159,.11);color:#fff}
.dialogue-choice b{color:var(--gold);margin-right:7px;font-size:9px}

/* ============================ PANEL SCREENS ============================ */
.panel-screen{z-index:40;background:rgba(3,6,12,.72);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);padding:clamp(8px,2.2vh,22px) clamp(8px,2.5vw,34px);display:flex;align-items:center;justify-content:center}
.panel-shell{width:min(1380px,96vw);height:min(870px,94vh);display:flex;flex-direction:column;background:linear-gradient(145deg,rgba(13,20,35,.98),rgba(6,9,17,.99));border:1px solid rgba(236,213,159,.22);box-shadow:0 40px 120px rgba(0,0,0,.8);position:relative}
.panel-shell::before{content:"";position:absolute;inset:5px;border:1px solid rgba(236,213,159,.05);pointer-events:none}
.panel-header{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:16px 24px;border-bottom:1px solid rgba(236,213,159,.15)}
.panel-header h2{font-family:var(--serif);font-weight:400;font-size:26px;letter-spacing:.03em;margin:2px 0 0}
.panel-header-right{display:flex;align-items:center;gap:16px;font-size:9px;letter-spacing:.1em;color:var(--muted);text-transform:uppercase}
.close-panel{width:30px;height:30px;border:1px solid rgba(255,255,255,.15);color:#cfc7b6;font-size:12px}
.close-panel:hover{border-color:var(--gold);color:var(--gold)}
.pause-layout{display:flex;flex:1;min-height:0}
.pause-nav{width:190px;flex:none;border-right:1px solid rgba(236,213,159,.12);padding:16px 10px;display:flex;flex-direction:column;gap:3px}
.pause-nav button{display:flex;align-items:center;gap:10px;padding:9px 12px;text-align:left;border-left:1px solid transparent;font-size:11px;color:rgba(246,239,223,.56);transition:.18s;letter-spacing:.04em}
.pause-nav button span{font-size:10px;text-transform:uppercase;letter-spacing:.1em}
.pause-nav button:hover{background:rgba(255,255,255,.04);color:#eee5d3}
.pause-nav button.active{border-left-color:var(--gold);background:linear-gradient(90deg,rgba(236,213,159,.11),transparent);color:var(--gold)}
.pause-nav .save-btn{margin-top:auto;border:1px solid rgba(236,213,159,.22);justify-content:center;color:var(--gold);font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.pause-nav .quit-btn{border:1px solid rgba(255,255,255,.08);justify-content:center;font-size:9px;text-transform:uppercase;color:rgba(246,239,223,.4)}
.pause-content{flex:1;overflow-y:auto;padding:20px 24px;scrollbar-width:thin;scrollbar-color:#6b5a38 #0a0f1a}
.tab-pane{display:none;animation:fadeIn .25s ease}
.tab-pane.active{display:block}
@keyframes fadeIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
.pane-title{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:15px}
.pane-title h3{font-family:var(--serif);font-weight:400;font-size:22px;margin:0}
.pane-title p{margin:0;font-size:10px;color:var(--muted);font-family:var(--serif);font-style:italic}
.hero-sheet{display:grid;grid-template-columns:250px 1fr;gap:22px}
.hero-art{border:1px solid var(--line);position:relative;overflow:hidden;min-height:330px;background:radial-gradient(ellipse at 50% 40%,rgba(65,83,111,.3),rgba(6,9,16,.8))}
#sheet-portrait{width:100%;height:100%;position:absolute;inset:0}
.hero-art-label{position:absolute;left:0;right:0;bottom:0;padding:12px;background:linear-gradient(0deg,rgba(5,8,14,.9),transparent);text-align:center}
.hero-art-label span{display:block;font-family:var(--serif);font-size:20px}
.hero-art-label small{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-2)}
.stat-header{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase;margin-bottom:4px}
.stat-header b{color:var(--gold);font-size:14px}
.xp-bar.big{height:5px;background:rgba(0,0,0,.5);margin-bottom:14px}
.xp-bar.big i{background:linear-gradient(90deg,#68aee8,#b69cff)}
.stat-list{display:grid;grid-template-columns:1fr 1fr;gap:5px 20px;margin-bottom:10px}
.stat-row{display:flex;align-items:center;justify-content:space-between;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.05);font-size:11px}
.stat-row>span{color:rgba(246,239,223,.62);display:flex;align-items:center;gap:6px}
.stat-row .stat-val{font-family:var(--serif);font-size:16px;color:#f1e7d0;min-width:30px;text-align:right}
.stat-row .stat-plus{width:18px;height:18px;border:1px solid rgba(236,213,159,.3);color:var(--gold);display:grid;place-items:center;font-size:12px;line-height:1;border-radius:2px}
.stat-row .stat-plus:hover{background:rgba(236,213,159,.15)}
.stat-row .stat-plus.disabled{opacity:.2;pointer-events:none}
.points-row{display:flex;align-items:center;justify-content:space-between;font-size:10px;color:var(--muted);margin:8px 0}
.points-row b{color:var(--gold);font-size:13px}
.derived-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
.derived-grid div{padding:7px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);text-align:center}
.derived-grid span{display:block;font-size:7px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.derived-grid b{font-family:var(--serif);font-size:14px;font-weight:400;color:var(--gold)}
.hero-bottom{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin-top:14px}
.equipment-slots{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}
.equip-slot{padding:9px;border:1px solid rgba(236,213,159,.13);background:rgba(255,255,255,.025);min-height:68px;cursor:pointer;transition:.18s}
.equip-slot:hover{border-color:rgba(236,213,159,.35);background:rgba(236,213,159,.05)}
.equip-slot span{display:block;font-size:6px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold-2);margin-bottom:4px}
.equip-slot b{display:block;font-size:10px;color:#e8e0d0;line-height:1.3}
.equip-slot small{font-size:8px;color:var(--green)}
.traits-card{padding:10px 12px}
.traits-card h4,.equipment-slots h4{margin:0 0 7px;font-size:8px;letter-spacing:.15em;text-transform:uppercase;color:var(--gold-2);font-weight:700}
.trait{display:flex;gap:7px;font-size:9px;color:rgba(246,239,223,.6);margin-bottom:5px;line-height:1.4}
.trait b{color:var(--gold);font-weight:600;white-space:nowrap}
.quest-columns{display:grid;grid-template-columns:1fr 1fr;gap:22px}
.quest-columns h4{font-size:8px;letter-spacing:.18em;text-transform:uppercase;color:var(--gold-2);margin:0 0 8px}
.quest-entry{border:1px solid rgba(255,255,255,.07);border-left:2px solid rgba(236,213,159,.3);background:rgba(255,255,255,.025);padding:10px 12px;margin-bottom:7px}
.quest-entry.done{border-left-color:var(--green);opacity:.65}
.quest-entry.active{border-left-color:var(--gold);background:linear-gradient(90deg,rgba(236,213,159,.08),transparent)}
.quest-entry h5{font-family:var(--serif);font-weight:400;font-size:13px;margin:0 0 3px;color:#eee5d3}
.quest-entry p{font-size:9px;line-height:1.5;color:var(--muted);margin:0}
.quest-entry .q-reward{font-size:8px;color:var(--gold-2);margin-top:4px;letter-spacing:.05em}
.creature-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(116px,1fr));gap:7px}
.creature-card{position:relative;border:1px solid rgba(255,255,255,.08);background:linear-gradient(160deg,rgba(255,255,255,.045),rgba(255,255,255,.01));padding:7px;text-align:center;cursor:pointer;transition:.18s;min-height:142px}
.creature-card:hover{border-color:rgba(236,213,159,.4);transform:translateY(-2px)}
.creature-card.locked{filter:grayscale(1);opacity:.32}
.creature-card.locked .c-name{color:#777}
.creature-card canvas{width:84px;height:84px;display:block;margin:0 auto}
.creature-card .c-name{font-family:var(--serif);font-size:11px;color:#eee6d4;display:block;margin-top:1px}
.creature-card .c-elem{font-size:6px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold-2)}
.creature-card .c-star{position:absolute;top:5px;right:6px;font-size:6px;color:var(--gold)}
.creature-detail{position:absolute;inset:auto 24px 20px 214px;background:rgba(7,11,20,.98);border:1px solid var(--line-strong);padding:16px;z-index:5;box-shadow:0 -20px 60px rgba(0,0,0,.6);display:grid;grid-template-columns:100px 1fr;gap:15px}
.creature-detail canvas{width:100px;height:100px}
.creature-detail h3{font-family:var(--serif);font-weight:400;margin:0;font-size:22px}
.creature-detail .cd-sub{font-size:7px;letter-spacing:.16em;color:var(--gold-2);text-transform:uppercase}
.creature-detail p{font-size:10px;line-height:1.55;color:var(--muted);margin:6px 0}
.creature-detail .cd-stats{display:flex;gap:12px;font-size:9px;color:var(--gold)}
.inventory-layout{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.inventory-layout h4{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-2);margin:0 0 7px}
.inventory-list{display:flex;flex-direction:column;gap:5px}
.inv-item{padding:8px 9px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.025);display:flex;justify-content:space-between;gap:8px;font-size:9px;align-items:center;cursor:pointer;transition:.18s}
.inv-item:hover{border-color:rgba(236,213,159,.35);background:rgba(236,213,159,.05)}
.inv-item b{display:block;font-size:10px;font-weight:500;color:#e9e1d0}
.inv-item small{font-size:7px;color:var(--muted)}
.inv-item .inv-count{color:var(--gold);font-size:9px;white-space:nowrap}
.inv-item.equipped{border-color:rgba(236,213,159,.4)}
.world-map-wrap{position:relative;border:1px solid rgba(236,213,159,.15);background:#070b13;overflow:hidden}
#world-map{width:100%;height:auto;display:block}
.map-tooltip{position:absolute;left:50%;bottom:10px;transform:translateX(-50%);padding:5px 10px;background:rgba(7,11,20,.9);border:1px solid var(--line);font-size:8px;letter-spacing:.08em;color:var(--muted)}
.region-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:8px}
.region-card{padding:8px 10px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.02);cursor:pointer;transition:.18s}
.region-card:hover{border-color:rgba(236,213,159,.3)}
.region-card b{display:block;font-family:var(--serif);font-weight:400;font-size:13px;color:#e9e1d0}
.region-card small{font-size:7px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.region-card.locked{opacity:.35}
.options-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}
.option-block{display:flex;flex-direction:column;gap:11px}
.option-block label{display:block;font-size:10px;color:var(--muted);letter-spacing:.04em}
.option-block input[type=range]{width:100%;accent-color:var(--gold-2);margin-top:5px}
.toggle-row{display:flex!important;justify-content:space-between;align-items:center;padding:8px 10px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.02)}
.toggle-row input{accent-color:var(--gold-2)}
.accessibility-note{padding:12px;border:1px solid rgba(236,213,159,.12);background:rgba(236,213,159,.03)}
.accessibility-note h4{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);margin:0 0 5px}
