cat > /tmp/opencode/mobiletest.mjs <<'EOF'
import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox','--disable-dev-shm-usage'] });
const ctx = await browser.newContext({ viewport: { width: 915, height: 412 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/opencode/m2-title.png', timeout: 30000 });
await page.evaluate(() => document.querySelector('#btn-new').click());
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/m2-creator.png', timeout: 30000 });
await page.evaluate(() => { document.querySelector('#screen-creator').scrollTop = 99999; });
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/m2-creator-bottom.png', timeout: 30000 });
await page.evaluate(() => document.querySelector('#btn-start-game').click());
await page.waitForTimeout(300);
for (let i = 0; i < 16; i++) { await page.evaluate(() => document.querySelector('#cine-skip')?.click()); await page.waitForTimeout(70); }
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/opencode/m2-game.png', timeout: 30000 });
// attack via touch button
const atkBefore = await page.evaluate(() => window.__S.player.attackTimer);
await page.evaluate(() => { const b=document.querySelector('.tbtn[data-action="attack"]'); b.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:1,pointerType:'touch'})); });
await page.waitForTimeout(150);
const atkAfter = await page.evaluate(() => ({timer:window.__S.player.attackTimer, mode:window.__S.mode}));
// open journal via touch pause
await page.evaluate(() => { const b=document.querySelector('.tbtn[data-action="pause"]'); b.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:2,pointerType:'touch'})); });
await page.waitForTimeout(400);
const pauseState = await page.evaluate(() => ({mode:window.__S.mode, panel:window.__S.panelTab, stats:document.querySelectorAll('.stat-row').length}));
await page.screenshot({ path: '/tmp/opencode/m2-panel.png', timeout: 30000 });
// options tab
await page.evaluate(() => document.querySelector('.pause-nav [data-tab="options"]').click());
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/opencode/m2-options.png', timeout: 30000 });
console.log(JSON.stringify({ errors, atkBefore, atkAfter, pauseState, touchDisplay: await page.evaluate(() => getComputedStyle(document.querySelector('#touch-controls')).display) }, null, 2));
await browser.close();
EOF
